cd /tmp && cat > /tmp/schema.php <<'EOF'
<?php
$pdo = new PDO('pgsql:host=postgres;port=5432;dbname=llmapi_eval', 'eval_rw', 'eval_rw', [PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
$q = $pdo->query("select table_schema, table_name, column_name, data_type, is_nullable, column_default from information_schema.columns where table_schema not in ('pg_catalog','information_schema') order by table_schema, table_name, ordinal_position");
foreach ($q as $r) echo implode(' | ', $r), "\n";
echo "--- constraints\n";
$q = $pdo->query("select conrelid::regclass, conname, pg_get_constraintdef(oid) from pg_constraint where connamespace='public'::regnamespace");
foreach ($q as $r) echo implode(' | ', $r), "\n";
echo "--- counts\n";
foreach (['author','book','customer','purchase','purchase_line'] as $t) { echo $t, ': ', $pdo->query("select count(*) from $t")->fetchColumn(), "\n"; }
echo "--- sample books\n";
foreach ($pdo->query("select * from book order by id limit 8") as $r) echo json_encode($r), "\n";
echo "--- sample authors\n";
foreach ($pdo->query("select * from author order by id limit 5") as $r) echo json_encode($r), "\n";
echo "--- sample customers\n";
foreach ($pdo->query("select * from customer order by id limit 5") as $r) echo json_encode($r), "\n";
echo "--- sample purchases\n";
foreach ($pdo->query("select * from purchase order by id limit 5") as $r) echo json_encode($r), "\n";
EOF
php -d display_errors=1 /tmp/schema.php 2>&1 | head -150

