<?php
$pdo = new PDO('pgsql:host=postgres;port=5432;dbname=llmapi_eval', 'eval_rw', 'eval_rw', [PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
$s = json_decode(file_get_contents($argv[1]), true);
